<?php $isEdit=!empty($account);?><div class="panel form-panel"><form method="post" action="<?= $isEdit?url('/users/'.$account['id'].'/update'):url('/users') ?>" class="form-grid"><?= csrf_field() ?>
<div class="field"><label>Nombre *</label><input name="name" value="<?= e(old('name',$account['name']??'')) ?>" required></div><div class="field"><label>Correo *</label><input type="email" name="email" value="<?= e(old('email',$account['email']??'')) ?>" required><?php if(error('email')):?><small class="error-text"><?= e(error('email')) ?></small><?php endif;?></div>
<div class="field"><label>Contraseña <?= $isEdit?'(dejar vacío para conservar)':'*' ?></label><input type="password" name="password" <?= $isEdit?'':'required' ?> autocomplete="new-password"><?php if(error('password')):?><small class="error-text"><?= e(error('password')) ?></small><?php endif;?></div>
<div class="field"><label>Rol *</label><select name="role" id="roleSelect"><option value="admin" <?= old('role',$account['role']??'receptionist')==='admin'?'selected':'' ?>>Administrador</option><option value="receptionist" <?= old('role',$account['role']??'receptionist')==='receptionist'?'selected':'' ?>>Recepción</option><option value="doctor" <?= old('role',$account['role']??'receptionist')==='doctor'?'selected':'' ?>>Médico</option></select></div>
<div class="field field-full" id="doctorField"><label>Médico asociado</label><select name="doctor_id"><option value="">Seleccionar</option><?php foreach($doctors as $d):?><option value="<?= $d['id'] ?>" <?= (int)old('doctor_id',$account['doctor_id']??0)===(int)$d['id']?'selected':'' ?>><?= e($d['name']) ?></option><?php endforeach;?></select><?php if(error('doctor_id')):?><small class="error-text"><?= e(error('doctor_id')) ?></small><?php endif;?></div>
<label class="switch-row field-full"><input type="checkbox" name="active" <?= (int)old('active',$account['active']??1)===1?'checked':'' ?>><span>Usuario activo</span></label><div class="form-actions field-full"><a class="btn" href="<?= url('/users') ?>">Cancelar</a><button class="btn btn-primary">Guardar usuario</button></div></form></div>
